import { useState, type FormEvent } from 'react';
import { JxStepper, JxInputField, JxButton } from '@jinx-ui/react';

interface RegistrationData {
  fullName: string;
  email: string;
  phone: string;
  city: string;
  street: string;
  postalCode: string;
}

interface RegistrationFormProps {
  onSubmit: (data: RegistrationData) => void;
}

const STEPS = [{ label: 'Контакты' }, { label: 'Адрес' }, { label: 'Проверка' }];

export default function RegistrationForm({ onSubmit }: RegistrationFormProps) {
  const [step, setStep] = useState(0);
  const [data, setData] = useState<RegistrationData>({
    fullName: '',
    email: '',
    phone: '',
    city: '',
    street: '',
    postalCode: '',
  });

  const update = (field: keyof RegistrationData) => (event: React.ChangeEvent<HTMLInputElement>) => {
    setData((prev) => ({ ...prev, [field]: event.target.value }));
  };

  const emailError =
    data.email.length > 0 && !data.email.includes('@') ? 'Укажите адрес с символом @' : undefined;

  const isLastStep = step === STEPS.length - 1;

  const canGoNext =
    step === 0
      ? data.fullName.trim().length > 0 && data.email.trim().length > 0 && !emailError
      : step === 1
        ? data.city.trim().length > 0 && data.street.trim().length > 0
        : true;

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (isLastStep) {
      onSubmit(data);
    } else if (canGoNext) {
      setStep((current) => Math.min(current + 1, STEPS.length - 1));
    }
  };

  return (
    <form
      onSubmit={handleSubmit}
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 'var(--jx-r-lg)',
        maxWidth: 420,
        padding: 'var(--jx-r-lg)',
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
        boxShadow: 'var(--jx-shadow-sm)',
      }}
    >
      <JxStepper steps={STEPS} current={step} />

      {step === 0 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-r)' }}>
          <JxInputField
            label="Полное имя"
            required
            value={data.fullName}
            onChange={update('fullName')}
            placeholder="Иван Иванов"
          />
          <JxInputField
            label="Электронная почта"
            type="email"
            required
            value={data.email}
            onChange={update('email')}
            errorText={emailError}
            placeholder="you@example.com"
          />
          <JxInputField
            label="Телефон"
            type="tel"
            prefix="+7"
            value={data.phone}
            onChange={update('phone')}
            placeholder="900 000-00-00"
          />
        </div>
      )}

      {step === 1 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-r)' }}>
          <JxInputField
            label="Город"
            required
            value={data.city}
            onChange={update('city')}
            placeholder="Москва"
          />
          <JxInputField
            label="Улица и дом"
            required
            value={data.street}
            onChange={update('street')}
            placeholder="ул. Ленина, 1"
          />
          <JxInputField
            label="Почтовый индекс"
            value={data.postalCode}
            onChange={update('postalCode')}
            placeholder="101000"
          />
        </div>
      )}

      {step === 2 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-r-sm)' }}>
          <div style={{ color: 'var(--jx-text-2)', fontSize: 13 }}>Проверьте данные перед отправкой</div>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 4, color: 'var(--jx-text)' }}>
            <span><strong>Имя:</strong> {data.fullName || '—'}</span>
            <span><strong>Email:</strong> {data.email || '—'}</span>
            <span><strong>Телефон:</strong> {data.phone ? `+7 ${data.phone}` : '—'}</span>
            <span><strong>Город:</strong> {data.city || '—'}</span>
            <span><strong>Адрес:</strong> {data.street || '—'}</span>
            <span><strong>Индекс:</strong> {data.postalCode || '—'}</span>
          </div>
        </div>
      )}

      <div style={{ display: 'flex', justifyContent: 'space-between', gap: 'var(--jx-r)' }}>
        <JxButton
          type="button"
          variant="ghost"
          disabled={step === 0}
          onClick={() => setStep((current) => Math.max(current - 1, 0))}
        >
          Назад
        </JxButton>
        <JxButton type="submit" variant="primary" disabled={!canGoNext}>
          {isLastStep ? 'Отправить' : 'Дальше'}
        </JxButton>
      </div>
    </form>
  );
}

